// @name Nonogram
// @background #f5f2ec
// @refresh 3600
// A daily nonogram (picross): the same puzzle on every frame on the same
// date, a new one at midnight. The numbers beside each row and over each
// column are the runs of filled squares in it, in order; fill the squares
// they ask for and a picture appears. Tap a square to fill it, again to mark
// it empty (an X), again to clear it; Mark switches taps to X's, and a held
// square does the other. On a frame with buttons, next and previous walk the
// squares and OK taps one. Every puzzle has exactly one solution, reached
// line by line without guessing, and today's progress is kept.
import { countFilled, cluesOf, dateKey, dateLabel, formatTime, isSolved, lineMatches, makePuzzle, nextLook, puzzleNumber, secondsToMidnight } from './logic'
import { fitBoard } from './board'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}
// Color e-paper (a Spectra panel's six inks) on Auto: a white page, black
// ink and solid colors only, since greys and pale tints dither to confetti.
const inkPaper = (app) => (app.state.contrast || 'auto') === 'auto' && app.frame.paper === true && app.frame.color !== false

const THEMES = {
  color: {
    page: 'bg-[#f5f2ec] text-[#26303b]',
    muted: 'text-[#6c7682]',
    thick: 'bg-[#2e3f52]',
    thin: 'bg-[#a9b4bf]',
    blank: 'bg-[#fffdf9]',
    filled: 'bg-[#2e3f52]',
    cross: 'text-[#7d8894]',
    // The square the keys are on: a frame inside it.
    focus: '#e09a2b',
    focusOnFill: '#efc66f',
    band: 'bg-[#ebe5da]',
    clue: 'text-[#26303b] font-bold',
    clueDone: 'text-[#b7b0a5] font-normal',
    // A filled square's edge, and the pen that crosses a met clue off: none
    // here, where the lines show and a met clue dims.
    edge: '',
    slash: '',
    // The finished picture: the filled squares alone, in teal.
    solvedLines: 'bg-[#f5f2ec]',
    solvedFill: 'bg-[#2f6b66]',
    solvedBlank: 'bg-[#ebe5da]',
    tool: 'bg-[#e4ded4] text-[#26303b] active:bg-[#d6cfc3]',
    toolOn: 'bg-[#2e3f52] text-white',
    primary: 'bg-[#2f6b66] text-white active:bg-[#24524e]',
    card: 'bg-[#fffdf9] border-4 border-[#2e3f52] text-[#26303b]',
    accent: 'text-[#2f6b66]',
  },
  // Black on white, nothing grey: a met clue is crossed off with a slash
  // (a line through a 4 hides in its bar), and filled squares keep a white
  // edge, so a run of them can still be counted.
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    thick: 'bg-black',
    thin: 'bg-black',
    blank: 'bg-white',
    filled: 'bg-black',
    cross: 'text-black',
    focus: '#000000',
    focusOnFill: '#ffffff',
    band: '',
    clue: 'text-black font-bold',
    clueDone: 'text-black font-normal',
    edge: 'border-white',
    slash: 'text-black',
    solvedLines: 'bg-white',
    solvedFill: 'bg-black',
    solvedBlank: 'bg-white',
    tool: 'bg-white text-black border-2 border-black',
    toolOn: 'bg-black text-white',
    primary: 'bg-black text-white',
    card: 'bg-white border-4 border-black text-black',
    accent: 'text-black',
  },
  // Color e-paper: black squares, red X's and red pen on met clues, the
  // finished picture in blue.
  ink: {
    page: 'bg-white text-black',
    muted: 'text-black',
    thick: 'bg-black',
    thin: 'bg-black',
    blank: 'bg-white',
    filled: 'bg-black',
    cross: 'text-[#cc0000]',
    focus: '#cc0000',
    focusOnFill: '#ffff00',
    band: '',
    clue: 'text-black font-bold',
    clueDone: 'text-black font-normal',
    edge: 'border-white',
    slash: 'text-[#cc0000]',
    solvedLines: 'bg-white',
    solvedFill: 'bg-[#0033cc]',
    solvedBlank: 'bg-white',
    tool: 'bg-white text-black border-2 border-black',
    toolOn: 'bg-[#0033cc] text-white',
    primary: 'bg-[#006b2e] text-white',
    card: 'bg-white border-4 border-black text-black',
    accent: 'text-[#0033cc]',
  },
}
const themeOf = (app) => (highContrast(app) ? THEMES.high : inkPaper(app) ? THEMES.ink : THEMES.color)

// The size: the scene's setting, else 10x10, and 5x5 on a small or round panel.
const sizeOf = (app, W: number, H: number, round: boolean) => {
  const s = String(app.state.size ?? 'auto')
  if (s === '5' || s === '10' || s === '15') return Number(s)
  return round || Math.min(W, H) < 360 ? 5 : 10
}

// The day's puzzle: drawn once for each date and size and kept with
// frameos.remember (an ESP32 starts every render with a fresh module); the
// clues are worked out from it again.
let puzzle = null
const puzzleFor = (date: string, n: number) => {
  const key = `${date}:${n}`
  if (puzzle && puzzle.key === key) return puzzle
  const kept = frameos.recall('puzzle')
  let solution = kept && kept.key === key && typeof kept.solution === 'string' && kept.solution.length === n * n ? kept.solution : ''
  if (!solution) {
    solution = makePuzzle(date, n).solution
    frameos.remember('puzzle', { key, solution })
  }
  const { rows, cols } = cluesOf(solution, n)
  puzzle = {
    key,
    date,
    n,
    rows,
    cols,
    total: countFilled(solution),
    rowText: rows.map((clue) => (clue.length ? clue.join(' ') : '0')),
    colText: cols.map((clue) => (clue.length ? clue.join(' ') : '0')),
  }
  return puzzle
}

// Today's progress, kept on disk in the scene's private `progress` field:
// the date and, for each size played today, the squares as a string ("0"
// blank, "1" filled, "2" an X), when the first move was made and when it
// was solved. A new date starts over.
type Game = { cells: string; start: number; end: number }
const blankGame = (n: number): Game => ({ cells: '0'.repeat(n * n), start: 0, end: 0 })
const loadGame = (app, p): Game => {
  const kept = app.state.progress
  const game = kept && typeof kept === 'object' && kept.date === p.date && kept.games && typeof kept.games === 'object' ? kept.games[String(p.n)] : null
  const ok = game && typeof game.cells === 'string' && game.cells.length === p.n * p.n && /^[012]*$/.test(game.cells)
  return ok ? { cells: game.cells, start: Number(game.start) || 0, end: Number(game.end) || 0 } : blankGame(p.n)
}
const saveGame = (app, p, game: Game) => {
  const kept = app.state.progress
  const games = kept && typeof kept === 'object' && kept.date === p.date && kept.games && typeof kept.games === 'object' ? { ...kept.games } : {}
  games[String(p.n)] = game
  frameos.setState('progress', { date: p.date, games })
}

// What a tap changes, as signals: each square, whether each row's and each
// column's clue is met, the count of filled squares and the mode. A tap runs
// only the parts that read them, not get(). The game itself stays in the
// scene's `progress` field.
let looks = []
let rowsDone = []
let colsDone = []
const filled = signal(0)
const mode = signal('fill')
// The app get() last ran with: a handler plays on it.
let lastApp = null

const show = (p, game: Game) => {
  const n = p.n
  if (looks.length !== n * n) {
    looks = Array.from({ length: n * n }, () => signal('0'))
    rowsDone = Array.from({ length: n }, () => signal(false))
    colsDone = Array.from({ length: n }, () => signal(false))
  }
  for (let i = 0; i < n * n; i++) looks[i].value = game.cells[i]
  for (let r = 0; r < n; r++) rowsDone[r].value = lineMatches(p.rows[r], game.cells, r * n, 1, n)
  for (let c = 0; c < n; c++) colsDone[c].value = lineMatches(p.cols[c], game.cells, c, n, n)
  filled.value = countFilled(game.cells)
  mode.value = frameos.recall('mode') === 'mark' ? 'mark' : 'fill'
}

// A tap on square i, or with `other` a held one (the other mode). The tap
// that solves the puzzle sets no signal: get() draws the finished picture.
// Neither does a press by the frame's keys (`byKeys`): on e-paper presses
// come quicker than refreshes, and a signal set in the render that also
// moves the keys' ring on is not drawn, so get() draws it all.
// Exported for the tests, which play the puzzle get() last drew.
export const tapSquare = (i: number, other: boolean, byKeys = false) => {
  const app = lastApp
  const p = puzzle
  if (!app || !p) return
  // A tap while "Clear the grid?" asks only puts the question away.
  if (frameos.recall('confirm')) {
    frameos.remember('confirm', false)
    return
  }
  const game = loadGame(app, p)
  if (game.end) return
  const marking = (frameos.recall('mode') === 'mark') !== other
  const look = nextLook(game.cells[i], marking)
  const cells = game.cells.slice(0, i) + look + game.cells.slice(i + 1)
  const now = Date.now()
  const next = { cells, start: game.start || now, end: 0 }
  const n = p.n
  if (isSolved(cells, n, p.rows, p.cols)) {
    next.end = now
    saveGame(app, p, next)
    return
  }
  saveGame(app, p, next)
  if (byKeys) return
  looks[i].value = look
  const r = Math.floor(i / n)
  const c = i % n
  rowsDone[r].value = lineMatches(p.rows[r], cells, r * n, 1, n)
  colsDone[c].value = lineMatches(p.cols[c], cells, c, n, n)
  filled.value = countFilled(cells)
}

const setMode = (which: string, byKeys = false) => {
  frameos.remember('mode', which)
  if (!byKeys) mode.value = which
}

// Clear asks first, when there is anything to clear; the card it brings sets
// no signal, so get() draws it.
const askClear = () => {
  if (!lastApp || !puzzle) return
  const game = loadGame(lastApp, puzzle)
  if (/[12]/.test(game.cells)) frameos.remember('confirm', true)
}
const clearGrid = () => {
  if (lastApp && puzzle) saveGame(lastApp, puzzle, blankGame(puzzle.n))
  frameos.remember('confirm', false)
}

// The frame's Back puts "Clear the grid?" away; F and M (or X) on a keyboard
// switch between filling and marking.
export function onEvent(app, context) {
  lastApp = app
  if (context.event === 'back') {
    if (!frameos.recall('confirm')) return false
    frameos.remember('confirm', false)
    return true
  }
  if (context.event !== 'keyDown') return false
  const p = context.payload || {}
  if (p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '').toLowerCase()
  if (key === 'f') setMode('fill')
  else if (key === 'm' || key === 'x') setMode('mark')
  else return false
  return true
}

// The day's puzzle shows from the frame's midnight: a frame asleep then
// wakes for it, within the scene's own interval.
const wakeAtMidnight = (app, now: Date) => {
  const interval = Number(app.state.refreshInterval) || 3600
  const wait = Math.ceil(secondsToMidnight(now)) + 2
  if (wait < interval) frameos.setNextSleep(wait)
}

// A panel of 900 px or more on its shorter side at render scale 1 (a 13.3"
// color e-paper, 1200 px) draws the text and buttons that much larger (K),
// by halves. The board fills what it is given on every panel.
const uiOf = (W: number, H: number) => {
  const short = Math.min(W, H)
  const K = short >= 900 ? Math.min(3, Math.floor((short / 480) * 2) / 2) : 1
  const small = short < 360
  const k = (v: number) => Math.round(v * K)
  return {
    W,
    H,
    K,
    small,
    pad: k(small ? 8 : 16),
    gap: k(small ? 6 : 10),
    title: k(small ? 18 : 30),
    text: k(small ? 14 : 18),
    note: k(small ? 12 : 15),
    button: k(small ? 34 : 48),
  }
}

// The board's sizes stay one object while nothing they come from changes,
// so the memo()'d parts are given equal props.
let lastGeometry = null
let lastGeometryKey = ''
const geometryFor = (p, availW: number, availH: number, K: number) => {
  const maxCell = Math.round(64 * K)
  const key = `${p.key}|${availW}|${availH}|${K}`
  if (lastGeometry && lastGeometryKey === key) return lastGeometry
  lastGeometryKey = key
  lastGeometry = fitBoard(p.n, p.rows, p.cols, availW, availH, K, maxCell)
  return lastGeometry
}

const CrossGlyph = ({ px, cls = '', width = 1.2 }) => (
  <svg viewBox="0 0 10 10" className={`w-[${px}px] h-[${px}px] ${cls}`}>
    <path d="M2.4 2.4L7.6 7.6M7.6 2.4L2.4 7.6" fill="none" stroke="currentColor" strokeWidth={width} strokeLinecap="round" />
  </svg>
)
const FillGlyph = ({ px }) => (
  <svg viewBox="0 0 10 10" className={`w-[${px}px] h-[${px}px]`}>
    <rect x={1.5} y={1.5} width={7} height={7} rx={1} fill="currentColor" />
  </svg>
)

// One square: blank, filled or an X, and a frame inside it while the keys
// are on it. Once solved, the picture alone and nothing to tap.
const Cell = memo(({ i, x, y, s, t, done }) => {
  const look = looks[i].value
  const box = `absolute left-[${x}px] top-[${y}px] w-[${s}px] h-[${s}px]`
  if (done) return <div className={`${box} ${look === '1' ? t.solvedFill : t.solvedBlank}`} />
  const isFilled = look === '1'
  const ring = Math.max(2, Math.round(s * 0.14))
  const edge = isFilled && t.edge ? `border-[${s >= 30 ? 2 : 1}px] ${t.edge}` : ''
  return (
    <div className={`${box} flex items-center justify-center ${isFilled ? t.filled : t.blank} ${edge} focus:border-[${ring}px] focus:border-[${isFilled ? t.focusOnFill : t.focus}]`}
      onClick={(e) => tapSquare(i, false, !!e?.key)}
      onLongPress={() => tapSquare(i, true)}>
      {look === '2' ? <CrossGlyph px={Math.round(s * 0.8)} cls={t.cross} width={s < 24 ? 1.5 : 1.2} /> : null}
    </div>
  )
})

// One number of a clue; crossed off with a slash, as with a pen, where the
// theme has one and its line is met.
const Num = ({ v, cls, slash }) =>
  slash ? (
    <div className={`relative ${cls}`}>
      {v}
      <svg viewBox="0 0 10 10" preserveAspectRatio="none" className={`absolute inset-0 w-full h-full ${slash}`}>
        <path d="M0.5 9.5L9.5 0.5" fill="none" stroke="currentColor" strokeWidth={1.4} strokeLinecap="round" />
      </svg>
    </div>
  ) : (
    <div className={cls}>{v}</div>
  )

// A row's clue, right-aligned beside it; dimmed (crossed off in high
// contrast) once the row's filled squares match it. A solved puzzle's clues
// all match, and are left plain there.
const RowClue = memo(({ r, y, w, g, t, text, done }) => {
  const met = rowsDone[r].value
  const slash = met && !done ? t.slash : ''
  const cls = `text-[${g.font}px] leading-none ${met ? t.clueDone : t.clue}`
  return (
    <div className={`absolute left-0 top-[${y}px] w-[${w}px] h-[${g.cell}px] flex items-center justify-end gap-[${g.numGap}px] pr-[${g.pad}px] ${t.band}`}>
      {text.split(' ').map((v) => <Num v={v} cls={cls} slash={slash} />)}
    </div>
  )
})

// A column's clue, stacked over it from the top down.
const ColClue = memo(({ c, x, h, g, t, text, done }) => {
  const met = colsDone[c].value
  const slash = met && !done ? t.slash : ''
  const cls = `h-[${g.lineH}px] flex items-center text-[${g.font}px] leading-none ${met ? t.clueDone : t.clue}`
  return (
    <div className={`absolute left-[${x}px] top-0 w-[${g.cell}px] h-[${h}px] flex flex-col items-center justify-end pb-[${g.pad}px] ${t.band}`}>
      {text.split(' ').map((v) => <Num v={v} cls={cls} slash={slash} />)}
    </div>
  )
})

// The board: the clues, the grid with a heavier line every five squares, and
// a card over it while it asks to be cleared.
const Board = ({ p, g, t, done, card }) => {
  const n = p.n
  const parts = []
  const gap = Math.max(2, g.thin * 2)
  for (let r = 0; r < n; r++) parts.push(<RowClue r={r} y={g.clueH + g.offs[r]} w={g.clueW - gap} g={g} t={t} text={p.rowText[r]} done={done} />)
  for (let c = 0; c < n; c++) parts.push(<ColClue c={c} x={g.clueW + g.offs[c]} h={g.clueH - gap} g={g} t={t} text={p.colText[c]} done={done} />)
  parts.push(<div className={`absolute left-[${g.clueW}px] top-[${g.clueH}px] w-[${g.grid}px] h-[${g.grid}px] ${done ? t.solvedLines : t.thick}`} />)
  // Each block of five by five: the thin lines' color behind its squares.
  for (let br = 0; br < n; br += 5) {
    for (let bc = 0; bc < n; bc += 5) {
      const x = g.clueW + g.offs[bc]
      const y = g.clueH + g.offs[br]
      const w = g.offs[Math.min(n, bc + 5) - 1] + g.cell - g.offs[bc]
      const h = g.offs[Math.min(n, br + 5) - 1] + g.cell - g.offs[br]
      parts.push(<div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px] ${done ? t.solvedLines : t.thin}`} />)
    }
  }
  for (let i = 0; i < n * n; i++) {
    parts.push(<Cell i={i} x={g.clueW + g.offs[i % n]} y={g.clueH + g.offs[Math.floor(i / n)]} s={g.cell} t={t} done={done} />)
  }
  return (
    <div className={`relative w-[${g.width}px] h-[${g.height}px] shrink-0`}>
      {parts}
      {card}
    </div>
  )
}

const Button = ({ h, font, cls, onClick, children, w = 0 }) => (
  <div className={`${w ? `w-[${w}px]` : 'flex-1 basis-0 min-w-0'} h-[${h}px] px-[${Math.round(font * 0.5)}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${font}px] font-bold ${cls}`}
    onClick={onClick}>
    {children}
  </div>
)

// Fill and Mark, the one taps do lit.
const ModeButton = memo(({ which, h, font, t, w, bare }) => {
  const on = mode.value === which
  const icon = Math.round(font * 0.95)
  return (
    <div className={`${w ? `w-[${w}px]` : 'flex-1 basis-0 min-w-0'} h-[${h}px] rounded-xl flex items-center justify-center gap-[${Math.round(font * 0.3)}px] whitespace-nowrap text-[${font}px] font-bold ${on ? t.toolOn : t.tool}`}
      onClick={(e) => setMode(which, !!e?.key)}>
      {bare ? null : which === 'fill' ? <FillGlyph px={icon} /> : <CrossGlyph px={icon} width={1.6} />}
      <span>{which === 'fill' ? 'Fill' : 'Mark'}</span>
    </div>
  )
})

const HOW = 'Each number is a run of filled squares in its row or column, in order, with at least one blank between runs. Tap a square to fill it, again for an X, again to clear it.'

// How many squares are filled, of how many the clues ask for.
const Count = memo(({ total, cls }) => <span className={cls}>{`${filled.value} of ${total} filled`}</span>)

const confirmCard = (g, t, ui) => {
  const w = Math.min(g.width - 8, Math.round(Math.max(220 * ui.K, g.width * 0.8)))
  const font = ui.text
  return (
    <div className={`absolute left-[${Math.round((g.width - w) / 2)}px] top-[${Math.round(g.height * 0.3)}px] w-[${w}px] rounded-2xl p-[${Math.round(font * 0.9)}px] flex flex-col items-center gap-[${Math.round(font * 0.6)}px] ${t.card}`}>
      <span className={`text-[${Math.round(font * 1.3)}px] font-bold text-center`}>Clear the grid?</span>
      <span className={`text-[${ui.note}px] text-center`}>Today's moves start over.</span>
      <div className={`flex w-full gap-[${Math.round(font * 0.6)}px]`}>
        <Button h={ui.button} font={font} cls={t.tool} onClick={() => frameos.remember('confirm', false)}>Cancel</Button>
        <Button h={ui.button} font={font} cls={t.primary} onClick={clearGrid}>Clear</Button>
      </div>
    </div>
  )
}

export function get(app, context) {
  lastApp = app
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const round = context?.round === true
  const t = themeOf(app)
  const now = new Date(Date.now())
  const date = dateKey(now)
  wakeAtMidnight(app, now)
  // A new day: yesterday's progress goes.
  const kept = app.state.progress
  if (!kept || typeof kept !== 'object' || kept.date !== date) frameos.setState('progress', { date, games: {} })
  const n = sizeOf(app, W, H, round)
  const p = puzzleFor(date, n)
  const game = loadGame(app, p)
  const done = game.end > 0
  show(p, game)
  const ui = uiOf(W, H)
  const card = !done && frameos.recall('confirm') ? true : false
  const number = `No. ${puzzleNumber(date)}`
  const solvedIn = done ? `Solved in ${formatTime(game.end - (game.start || game.end))}` : ''

  if (round) return roundPage(ui, t, p, done, card, number, solvedIn)

  const wide = W >= H * 1.15
  if (wide) {
    // The board on the left as tall as the panel, the rest beside it.
    const sideMin = Math.round(Math.max(200 * ui.K, W * 0.27))
    const g = geometryFor(p, W - 3 * ui.pad - sideMin, H - 2 * ui.pad, ui.K)
    const sideW = W - 3 * ui.pad - g.width
    const titleFont = Math.min(ui.title, Math.floor(sideW / 5.4))
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        <div className="flex-1 h-full flex items-center justify-center">
          <Board p={p} g={g} t={t} done={done} card={card ? confirmCard(g, t, ui) : null} />
        </div>
        <div className={`w-[${sideW}px] h-full flex flex-col gap-[${Math.round(ui.gap * 0.5)}px]`}>
          <span className={`text-[${titleFont}px] font-bold leading-tight`}>Nonogram</span>
          <span className={`text-[${ui.note}px] ${t.muted} truncate`}>{`${number} · ${dateLabel(date)} · ${n}×${n}`}</span>
          {done ? null : <Count total={p.total} cls={`text-[${ui.text}px] mt-[${ui.gap}px]`} />}
          {!done && H - 2 * ui.pad >= 360 * ui.K ? (
            <span className={`text-[${ui.note}px] leading-snug mt-[${ui.gap}px] ${t.muted}`}>{HOW}</span>
          ) : null}
          <div className="flex-1" />
          {done ? (
            <div className={`flex flex-col gap-[${Math.round(ui.gap * 0.5)}px]`}>
              <span className={`text-[${Math.round(ui.title * 0.9)}px] font-bold leading-tight ${t.accent}`}>{solvedIn}</span>
              <span className={`text-[${ui.note}px] ${t.muted}`}>A new puzzle at midnight</span>
            </div>
          ) : (
            <div className={`flex flex-col gap-[${ui.gap}px]`}>
              <div className={`flex gap-[${ui.gap}px]`}>
                <ModeButton which="fill" h={ui.button} font={ui.text} t={t} w={0} bare={false} />
                <ModeButton which="mark" h={ui.button} font={ui.text} t={t} w={0} bare={false} />
              </div>
              <div className="flex">
                <Button h={ui.button} font={ui.text} cls={t.tool} onClick={askClear}>Clear</Button>
              </div>
            </div>
          )}
        </div>
      </div>
    )
  }

  // Tall or square: the title and the count, the board, the buttons below,
  // and how to play under the title where the board leaves room for it.
  const headH = Math.round(ui.title * 1.25) + Math.round(ui.note * 1.4)
  const availH = H - 2 * ui.pad - headH - ui.button - 2 * ui.gap
  const g = geometryFor(p, W - 2 * ui.pad, availH, ui.K)
  const howLines = Math.ceil((HOW.length * ui.note * 0.5) / (W - 2 * ui.pad)) + 1
  const how = !done && availH - g.height >= howLines * ui.note * 1.375 + ui.gap
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
      <div className="flex flex-col">
        <div className="flex items-end justify-between gap-2">
          <span className={`text-[${ui.title}px] font-bold leading-tight`}>Nonogram</span>
          {done ? (
            <span className={`text-[${ui.text}px] font-bold ${t.accent}`}>Solved</span>
          ) : (
            <Count total={p.total} cls={`text-[${ui.text}px] pb-[2px]`} />
          )}
        </div>
        <span className={`text-[${ui.note}px] ${t.muted} truncate`}>{`${number} · ${dateLabel(date)}`}</span>
        {how ? <span className={`text-[${ui.note}px] leading-snug mt-[${ui.gap}px] ${t.muted}`}>{HOW}</span> : null}
      </div>
      <div className="flex-1 min-h-0 flex items-center justify-center">
        <Board p={p} g={g} t={t} done={done} card={card ? confirmCard(g, t, ui) : null} />
      </div>
      {done ? (
        <div className={`h-[${ui.button}px] flex items-center justify-between gap-2`}>
          <span className={`text-[${ui.text}px] font-bold ${t.accent}`}>{solvedIn}</span>
          <span className={`text-[${ui.note}px] ${t.muted} truncate`}>New at midnight</span>
        </div>
      ) : (
        <div className={`flex gap-[${ui.gap}px]`}>
          <ModeButton which="fill" h={ui.button} font={ui.text} t={t} w={0} bare={ui.small} />
          <ModeButton which="mark" h={ui.button} font={ui.text} t={t} w={0} bare={ui.small} />
          <Button h={ui.button} font={ui.text} cls={t.tool} onClick={askClear}>Clear</Button>
        </div>
      )}
    </div>
  )
}

// A round panel: the board in the square inside the circle, the number and
// the count in the arc above it, Fill, Mark and Clear in the arc below, as
// wide as the circle is there.
const roundPage = (ui, t, p, done: boolean, card: boolean, number: string, solvedIn: string) => {
  const { W, H } = ui
  const cx = W / 2
  const cy = H / 2
  const R = Math.min(W, H) / 2 - 12
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const side = Math.floor(R * Math.SQRT2)
  const g = geometryFor(p, side, side - Math.round(R * 0.12), ui.K)
  const left = Math.round(cx - g.width / 2)
  const top = Math.round(cy - g.height / 2 - R * 0.04)
  const bottom = top + g.height
  const font = Math.max(14, Math.round(R * 0.072))
  const btnH = Math.max(36, Math.round(R * 0.18))
  const btnTop = bottom + 8
  const rowW = Math.min(chord(btnTop + btnH - cy) - 8, Math.round(R * 1.2))
  const headH = Math.round(font * 1.3)
  const headTop = top - headH - 4
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-0 top-[${headTop}px] w-[${W}px] h-[${headH}px] flex items-center justify-center gap-[8px] text-[${font}px]`}>
        <span className="font-bold">{number}</span>
        {done ? <span className={`font-bold ${t.accent}`}>Solved</span> : <Count total={p.total} cls={t.muted} />}
      </div>
      <div className={`absolute left-[${left}px] top-[${top}px]`}>
        <Board p={p} g={g} t={t} done={done} card={card ? confirmCard(g, t, ui) : null} />
      </div>
      <div className={`absolute left-[${Math.round(cx - rowW / 2)}px] top-[${btnTop}px] w-[${rowW}px] h-[${btnH}px] flex items-center justify-center gap-[6px]`}>
        {done ? (
          <span className={`text-[${font}px] font-bold ${t.accent}`}>{solvedIn}</span>
        ) : (
          [
            <ModeButton which="fill" h={btnH} font={font} t={t} w={0} bare={false} />,
            <ModeButton which="mark" h={btnH} font={font} t={t} w={0} bare={false} />,
            <Button h={btnH} font={font} cls={t.tool} onClick={askClear}>Clear</Button>,
          ]
        )}
      </div>
    </div>
  )
}

