// Nonogram's rules. Pure: no frameos calls, so the tests can check them alone.
//
// A grid is a string, one character a square, row by row: "1" filled, "0"
// blank, "2" marked empty (an X). A solution uses "1" and "0" alone.

// The puzzles are numbered from this day: 1 January 2026 is No. 1.
const EPOCH_DAY = Date.UTC(2026, 0, 1) / 86400000

// The date as YYYY-MM-DD in the frame's time zone (Date reads local time):
// the puzzle changes at the frame's midnight.
export function dateKey(date: Date): string {
  const m = date.getMonth() + 1
  const d = date.getDate()
  return `${date.getFullYear()}-${m < 10 ? '0' : ''}${m}-${d < 10 ? '0' : ''}${d}`
}

// The day a date key names, counted from 1970 (the same everywhere).
export function dayOf(key: string): number {
  const [y, m, d] = key.split('-').map(Number)
  return Math.round(Date.UTC(y, m - 1, d) / 86400000)
}

export function puzzleNumber(key: string): number {
  return dayOf(key) - EPOCH_DAY + 1
}

// A 32-bit seed from a text (FNV-1a).
export function seedOf(text: string): number {
  let h = 2166136261
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

// mulberry32: a small, fast PRNG; the same seed gives the same numbers on
// every frame. Never Math.random: every frame shows the same puzzle.
export function mulberry32(seed: number) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// The runs of filled squares along a line of a grid string: `n` squares from
// `start`, `step` apart (1 along a row, n down a column).
export function runsOf(cells: string, start: number, step: number, n: number): number[] {
  const runs: number[] = []
  let run = 0
  for (let i = 0; i < n; i++) {
    if (cells.charCodeAt(start + i * step) === 49) run++
    else if (run) {
      runs.push(run)
      run = 0
    }
  }
  if (run) runs.push(run)
  return runs
}

// Whether the filled squares of a line are exactly its clue.
export function lineMatches(clue: number[], cells: string, start: number, step: number, n: number): boolean {
  const runs = runsOf(cells, start, step, n)
  if (runs.length !== clue.length) return false
  for (let i = 0; i < runs.length; i++) if (runs[i] !== clue[i]) return false
  return true
}

// The clues of a solution: each row's runs, left to right, and each column's,
// top to bottom. An empty line's clue is [] (drawn as 0).
export function cluesOf(solution: string, n: number) {
  const rows: number[][] = []
  const cols: number[][] = []
  for (let r = 0; r < n; r++) rows.push(runsOf(solution, r * n, 1, n))
  for (let c = 0; c < n; c++) cols.push(runsOf(solution, c, n, n))
  return { rows, cols }
}

// Solved means every line matches its clue: any grid that does counts, X or
// not, whether or not it is the picture the puzzle was made from.
export function isSolved(cells: string, n: number, rows: number[][], cols: number[][]): boolean {
  for (let r = 0; r < n; r++) if (!lineMatches(rows[r], cells, r * n, 1, n)) return false
  for (let c = 0; c < n; c++) if (!lineMatches(cols[c], cells, c, n, n)) return false
  return true
}

// What a tap does to a square. Filling: blank, filled, X, blank again.
// Marking: an X, or blank again.
export function nextLook(look: string, marking: boolean): string {
  if (marking) return look === '2' ? '0' : '2'
  return look === '0' ? '1' : look === '1' ? '2' : '0'
}

export function countFilled(cells: string): number {
  let filled = 0
  for (let i = 0; i < cells.length; i++) if (cells.charCodeAt(i) === 49) filled++
  return filled
}

// ------------------------------------------------------------ the line solver
//
// One line at a time: of every way its runs can be laid along the line that
// agrees with what is known, a square every way fills is filled, a square
// every way leaves blank is blank. Repeated over the rows and columns until
// nothing more follows, as a person solves a nonogram without guessing.
// Line values: 0 unknown, 1 filled, 2 empty.

const MAX = 16
const fits = new Uint8Array((MAX + 1) * (MAX + 1)) // squares i.. can hold runs j..
const reach = new Uint8Array((MAX + 1) * (MAX + 1)) // squares ..i can hold runs ..j, every way that can go on
const empties = new Int16Array(MAX + 1) // known empty squares before i
const fillMarks = new Int16Array(MAX + 1) // where a run that fits starts (+1) and ends (-1)
const canBeEmpty = new Uint8Array(MAX)

// Settles what it can of `line` (changed in place) and answers how many
// squares it settled, or -1 when no way of laying the runs fits.
export function solveLine(line: Uint8Array, n: number, runs: number[]): number {
  const k = runs.length
  const K1 = k + 1
  empties[0] = 0
  for (let i = 0; i < n; i++) empties[i + 1] = empties[i] + (line[i] === 2 ? 1 : 0)
  // From the end: can squares i.. hold runs j..?
  for (let j = 0; j <= k; j++) fits[n * K1 + j] = j === k ? 1 : 0
  for (let i = n - 1; i >= 0; i--) {
    for (let j = k; j >= 0; j--) {
      let ok = 0
      if (line[i] !== 1 && fits[(i + 1) * K1 + j]) ok = 1
      else if (j < k) {
        const end = i + runs[j]
        if (end <= n && empties[end] === empties[i] && (end === n || line[end] !== 1)) {
          if (fits[(end === n ? n : end + 1) * K1 + j + 1]) ok = 1
        }
      }
      fits[i * K1 + j] = ok
    }
  }
  if (!fits[0]) return -1
  // From the start: every step of a way that fits marks what it does to the
  // squares it covers.
  reach.fill(0, 0, (n + 1) * K1)
  fillMarks.fill(0, 0, n + 1)
  canBeEmpty.fill(0, 0, n)
  reach[0] = 1
  for (let i = 0; i < n; i++) {
    for (let j = 0; j <= k; j++) {
      if (!reach[i * K1 + j]) continue
      // Square i left blank.
      if (line[i] !== 1 && fits[(i + 1) * K1 + j]) {
        canBeEmpty[i] = 1
        reach[(i + 1) * K1 + j] = 1
      }
      // Run j laid from square i, and the blank after it.
      if (j < k) {
        const end = i + runs[j]
        if (end <= n && empties[end] === empties[i] && (end === n || line[end] !== 1)) {
          const next = end === n ? n : end + 1
          if (fits[next * K1 + j + 1]) {
            fillMarks[i]++
            fillMarks[end]--
            if (end < n) canBeEmpty[end] = 1
            reach[next * K1 + j + 1] = 1
          }
        }
      }
    }
  }
  let settled = 0
  let covered = 0
  for (let i = 0; i < n; i++) {
    covered += fillMarks[i]
    if (line[i] !== 0) continue
    const fill = covered > 0
    const empty = canBeEmpty[i] === 1
    if (fill && !empty) {
      line[i] = 1
      settled++
    } else if (empty && !fill) {
      line[i] = 2
      settled++
    } else if (!fill && !empty) return -1
  }
  return settled
}

// Solves the whole grid line by line. `grid` holds 0 / 1 / 2 a square;
// `solved` is true when nothing is left unknown, and then the solution is
// the only one there is (every step was forced). `broken`: the clues
// contradict each other.
export function lineSolve(n: number, rows: number[][], cols: number[][]) {
  const grid = new Uint8Array(n * n)
  const line = new Uint8Array(n)
  const rowDirty = new Uint8Array(n).fill(1)
  const colDirty = new Uint8Array(n).fill(1)
  let busy = true
  while (busy) {
    busy = false
    for (let r = 0; r < n; r++) {
      if (!rowDirty[r]) continue
      rowDirty[r] = 0
      for (let i = 0; i < n; i++) line[i] = grid[r * n + i]
      const got = solveLine(line, n, rows[r])
      if (got < 0) return { grid, solved: false, broken: true }
      if (got === 0) continue
      for (let i = 0; i < n; i++) {
        if (grid[r * n + i] !== line[i]) {
          grid[r * n + i] = line[i]
          colDirty[i] = 1
          busy = true
        }
      }
    }
    for (let c = 0; c < n; c++) {
      if (!colDirty[c]) continue
      colDirty[c] = 0
      for (let i = 0; i < n; i++) line[i] = grid[i * n + c]
      const got = solveLine(line, n, cols[c])
      if (got < 0) return { grid, solved: false, broken: true }
      if (got === 0) continue
      for (let i = 0; i < n; i++) {
        if (grid[i * n + c] !== line[i]) {
          grid[i * n + c] = line[i]
          rowDirty[i] = 1
          busy = true
        }
      }
    }
  }
  let solved = true
  for (let i = 0; i < n * n; i++) {
    if (grid[i] === 0) {
      solved = false
      break
    }
  }
  return { grid, solved, broken: false }
}

// ------------------------------------------------------------ the day's puzzle
//
// Drawn from a PRNG seeded with the date and the size: about 55 percent of
// the squares filled, and on about half the days the picture mirrored left to
// right (a sprite). A grid the line solver cannot finish (more than one
// solution, or one that needs a guess) is dropped and the next is drawn from
// the same stream, so every frame lands on the same one. A 15x15 needs two
// draws on average.
export function makePuzzle(key: string, n: number) {
  const rand = mulberry32(seedOf(`nonogram ${key} ${n}`))
  const cells = new Uint8Array(n * n)
  let solution = ''
  let attempts = 0
  while (attempts < 500) {
    attempts++
    const density = 0.5 + rand() * 0.1
    const mirror = rand() < 0.5
    const across = mirror ? Math.ceil(n / 2) : n
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < across; c++) {
        const filled = rand() < density ? 1 : 0
        cells[r * n + c] = filled
        if (mirror) cells[r * n + n - 1 - c] = filled
      }
    }
    solution = ''
    for (let i = 0; i < n * n; i++) solution += cells[i] ? '1' : '0'
    const { rows, cols } = cluesOf(solution, n)
    if (lineSolve(n, rows, cols).solved) break
  }
  return { key, n, solution, attempts }
}

// ------------------------------------------------------------ time

// Seconds from `now` to the frame's next midnight.
export function secondsToMidnight(now: Date): number {
  const next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0, 0)
  return Math.max(0, (next.getTime() - now.getTime()) / 1000)
}

// 4:05, or 1:02:05 past an hour.
export function formatTime(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  const two = (v: number) => (v < 10 ? '0' : '') + v
  if (s >= 3600) return `${Math.floor(s / 3600)}:${two(Math.floor(s / 60) % 60)}:${two(s % 60)}`
  return `${Math.floor(s / 60)}:${two(s % 60)}`
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

// "Sat 28 Nov", from the date key alone.
export function dateLabel(key: string, weekday = true): string {
  const [y, m, d] = key.split('-').map(Number)
  const day = DAYS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()]
  return `${weekday ? `${day} ` : ''}${d} ${MONTHS[m - 1]}`
}

