// Where the board's parts go, in pixels: the clues along the top and the
// left, the grid with a heavier line every five squares. Pure, so the tests
// can check that a board fits.

export type Geometry = {
  n: number
  cell: number
  font: number
  thin: number
  thick: number
  numGap: number
  pad: number
  lineH: number
  clueW: number
  clueH: number
  grid: number
  width: number
  height: number
  // Each row's (and column's) offset from the grid's corner.
  offs: number[]
}

export function measure(n: number, rows: number[][], cols: number[][], cell: number, K: number): Geometry {
  // Small squares get bigger numbers for their size.
  const font = Math.max(9, Math.min(Math.round(26 * K), Math.round(cell * (cell < 30 ? 0.62 : 0.5))))
  const thin = Math.max(1, Math.round(cell * 0.05))
  const thick = Math.max(2, Math.round(cell * 0.1))
  const numGap = Math.max(3, Math.round(font * 0.42))
  const pad = Math.max(3, Math.round(font * 0.35))
  const lineH = Math.round(font * 1.12)
  // A digit of the bold face is about 0.6 of its size.
  const digitW = font * 0.6
  let widest = 0
  for (const clue of rows) {
    let digits = 0
    for (const v of clue) digits += v >= 10 ? 2 : 1
    const w = Math.max(1, digits) * digitW + Math.max(0, clue.length - 1) * numGap
    if (w > widest) widest = w
  }
  let tallest = 1
  for (const clue of cols) if (clue.length > tallest) tallest = clue.length
  const clueW = Math.ceil(widest + 2 * pad)
  const clueH = tallest * lineH + 2 * pad
  const groups = Math.floor((n - 1) / 5)
  const grid = 2 * thick + n * cell + (n - 1 - groups) * thin + groups * thick
  const offs: number[] = []
  for (let i = 0; i < n; i++) offs.push(thick + i * cell + i * thin + Math.floor(i / 5) * (thick - thin))
  return { n, cell, font, thin, thick, numGap, pad, lineH, clueW, clueH, grid, width: clueW + grid, height: clueH + grid, offs }
}

// The largest board that fits `availW` x `availH`, its squares at most
// `maxCell` across.
export function fitBoard(n: number, rows: number[][], cols: number[][], availW: number, availH: number, K: number, maxCell: number): Geometry {
  let cell = Math.max(5, Math.min(maxCell, Math.floor(Math.min(availW, availH) / n)))
  for (; cell > 5; cell--) {
    const g = measure(n, rows, cols, cell, K)
    if (g.width <= availW && g.height <= availH) return g
  }
  return measure(n, rows, cols, 5, K)
}

